import httpx
from fastapi import FastAPI, Depends, HTTPException
from fastapi.testclient import TestClient
UPSTREAM_URL = 'https://upstream.invalid/lookup'  # Authored mock-only URL, never a provisioned service.
app = FastAPI()
async def client_provider():
    async with httpx.AsyncClient() as client:
        yield client
async def lookup(client):
    try:
        response = await client.get(UPSTREAM_URL)
        response.raise_for_status()
        return response.json()
    except httpx.HTTPStatusError as exc:
        raise HTTPException(status_code=502, detail='Upstream unavailable') from None
    except httpx.RequestError as exc:
        if isinstance(exc, httpx.TimeoutException):
            raise HTTPException(status_code=504, detail='Upstream timed out') from None
        else:
            raise HTTPException(status_code=502, detail='Upstream unavailable') from None
@app.get('/lookup')
async def route(client=Depends(client_provider)):
    return await lookup(client)
def status_failure(request):
    return httpx.Response(503, request=request)
def timeout_failure(request):
    raise httpx.ReadTimeout('Controlled timeout', request=request)

from fastapi import Request
async def controlled_client(request: Request):
    handler = status_failure if request.headers.get("X-Fixture") == "upstream_503" else timeout_failure
    async with httpx.AsyncClient(transport=httpx.MockTransport(handler)) as client:
        yield client
app.dependency_overrides[client_provider] = controlled_client

